from bisect import bisect_left, insort
class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        window = []
        ans = float('inf')
        for j in range(len(nums)):
            if j >= x:
                insort(window, nums[j - x])
                k = bisect_left(window, nums[j])
                if k < len(window): ans = min(ans, window[k] - nums[j])
                if k > 0: ans = min(ans, nums[j] - window[k - 1])
        return ans

