class Solution {
public:
    int minAbsoluteDifference(vector<int>& nums, int x) {
        multiset<int> s;
        int ans = INT_MAX;
        for (int j = 0; j < nums.size(); ++j) {
            if (j >= x) {
                s.insert(nums[j - x]);
                auto it = s.lower_bound(nums[j]);
                if (it != s.end()) ans = min(ans, *it - nums[j]);
                if (it != s.begin()) ans = min(ans, nums[j] - *prev(it));
            }
        }
        return ans;
    }
};

