class Solution {
    public int minAbsoluteDifference(List<Integer> nums, int x) {
        TreeSet<Integer> s = new TreeSet<>();
        int ans = Integer.MAX_VALUE;
        for (int j = 0; j < nums.size(); j++) {
            if (j >= x) {
                s.add(nums.get(j - x));
                Integer hi = s.ceiling(nums.get(j)), lo = s.floor(nums.get(j));
                if (hi != null) ans = Math.min(ans, hi - nums.get(j));
                if (lo != null) ans = Math.min(ans, nums.get(j) - lo);
            }
        }
        return ans;
    }
}

