var minAbsoluteDifference = function(nums, x) {
    const window = [];
    let ans = Infinity;
    const lowerBound = (arr, v) => { let lo = 0, hi = arr.length;
        while (lo < hi) { const m = (lo + hi) >> 1; arr[m] < v ? lo = m + 1 : hi = m; } return lo; };
    for (let j = 0; j < nums.length; j++) {
        if (j >= x) {
            window.splice(lowerBound(window, nums[j - x]), 0, nums[j - x]);
            const k = lowerBound(window, nums[j]);
            if (k < window.length) ans = Math.min(ans, window[k] - nums[j]);
            if (k > 0) ans = Math.min(ans, nums[j] - window[k - 1]);
        }
    }
    return ans;
};

