public:
    int minAbsoluteDifference(vector<int>& nums, int x) {
        int ans = INT_MAX;
        for (int i = 0; i < nums.size(); ++i)
            for (int j = i + x; j < nums.size(); ++j)
                ans = min(ans, abs(nums[i] - nums[j]));
        return ans;
    }
};

